(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+50)*0.035-t*0.5)*8+Math.cos((y-30)*0.028+t*0.4)*6;
  const wy2 = Math.cos((y+40)*0.03+t*0.45)*8+Math.sin((x-60)*0.025-t*0.38)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.6],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.3],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.55],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.75)*90, 0.11, 2.1, 0.45],
    [400+Math.cos(t*0.45+2)*60, 220+Math.sin(t*0.85+1)*50, 0.055, 2.4, 0.65]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,coupling] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    cS+=Math.sin(d*f*1.3-t*sp*0.8+2.0)*coupling;
  }
  const act=aS/8, inh=iS/8, coup=cS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07+sy*0.05-t*1.8)*0.15+Math.cos(sx*0.05-sy*0.08+t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2+t*2.0)*0.2+Math.cos(dist*0.03+ang*5-t*0.8)*0.15;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const ridge=Math.abs(Math.sin(dist*0.06-ang*2+t*1.0))-0.5;
  const diffusion=act-inh*0.7+bg*0.3+spiral+cell+coup*0.4+ridge*0.15;
  const feedback=Math.sin(diffusion*2.5-t*0.8)*0.2;
  const reaction=Math.tanh((diffusion+feedback)*2.0);
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend=reaction*0.7+cell*0.2+micro, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,95],[18,85,125],[25,135,135],
    [80,175,140],[180,195,80],[215,160,60],[200,110,55],
    [175,65,65],[120,35,75],[60,18,60],[20,10,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.08:0.95;
  const glow=Math.max(0, reaction*0.15);
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)
  ];
}
